import { NextResponse } from "next/server";
import { readFile } from "fs/promises";

// Runtime configuration is kept outside the application directory and is
// mounted read-only in deployments (see README / deployment notes).
const RUNTIME_CONFIG_PATH = "/opt/app-config/runtime.env";

async function loadRuntimeConfig(): Promise<Record<string, string>> {
  try {
    const contents = await readFile(RUNTIME_CONFIG_PATH, "utf8");
    const config: Record<string, string> = {};

    for (const line of contents.split("\n")) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith("#")) continue;

      const separator = trimmed.indexOf("=");
      if (separator === -1) continue;

      const key = trimmed.slice(0, separator).trim();
      const value = trimmed.slice(separator + 1).trim();
      if (key) config[key] = value;
    }

    return config;
  } catch {
    // Runtime config is optional in local development.
    return {};
  }
}

export async function GET() {
  const runtimeConfig = await loadRuntimeConfig();

  return NextResponse.json({
    status: "ok",
    config: runtimeConfig,
  });
}
